$ErrorActionPreference = "Stop"

Write-Host "=== FIX ROLE CRUD LENGKAP ===" -ForegroundColor Cyan
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupDir = Join-Path (Get-Location) ("backup-fix-role-crud-" + $stamp)
New-Item -ItemType Directory -Path $backupDir -Force | Out-Null

$files = @(
  "src\database.ts"
  "src\employee.ts"
  "src\attendance.ts"
  "src\report.ts"
  "src\xlsx.ts"
  "src\index.ts"
  "public\pegawai.html"
  "public\pegawai.js"
  "public\rekap-bulanan.html"
  "public\rekap-bulanan.js"
  "public\tambah-rekap.js"
  "public\edit-rekap.js"
)

foreach ($file in $files) {
  if (Test-Path $file) {
    $dest = Join-Path $backupDir $file
    $destDir = Split-Path $dest -Parent
    New-Item -ItemType Directory -Path $destDir -Force | Out-Null
    Copy-Item $file $dest -Force
  }
}

if (Test-Path ".\data\absensi.sqlite") {
  New-Item -ItemType Directory -Path (Join-Path $backupDir "data") -Force | Out-Null
  Copy-Item ".\data\absensi.sqlite" (Join-Path $backupDir "data\absensi.sqlite") -Force
}

