'@
$bytes = [Convert]::FromBase64String(($b11 -replace "\s", ""))
$target = Join-Path (Get-Location) "public\edit-rekap.js"
$targetDir = Split-Path $target -Parent
if (-not (Test-Path $targetDir)) { New-Item -ItemType Directory -Path $targetDir -Force | Out-Null }
[System.IO.File]::WriteAllBytes($target, $bytes)
Write-Host "OK: public\edit-rekap.js" -ForegroundColor Green

Write-Host ""
Write-Host "Build ulang TypeScript..." -ForegroundColor Cyan
npm run build
if ($LASTEXITCODE -ne 0) {
  Write-Host "BUILD GAGAL. File backup ada di: $backupDir" -ForegroundColor Red
  exit 1
}

Write-Host ""
Write-Host "FIX SELESAI." -ForegroundColor Green
Write-Host "Backup: $backupDir" -ForegroundColor Yellow
Write-Host "Sekarang jalankan: npm run dev" -ForegroundColor Cyan